<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/auth.php'; require_page('radiology.php');
$page_title='Radiologi'; $page_subtitle=is_role('radiology')?'RIS worklist dan reporting radiologis.':'Imaging result viewer untuk clinical team/pasien.'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'&&is_role('radiology')){
 check_csrf();$oid=(int)($_POST['order_id']??0);$s=$pdo->prepare("SELECT id FROM cpoe_orders WHERE id=? AND order_type='radiology' LIMIT 1");$s->execute([$oid]);
 if(!$s->fetchColumn()){$msg='Order radiologi tidak ditemukan.';}
 else{
  $q=$pdo->prepare('SELECT id FROM radiology_results WHERE order_id=? LIMIT 1');$q->execute([$oid]);$rid=$q->fetchColumn();
  if($rid){$q=$pdo->prepare('UPDATE radiology_results SET modality=?,technique=?,findings=?,impression=?,reported_by=?,reported_at=NOW() WHERE id=?');$q->execute([trim($_POST['modality']),trim($_POST['technique']),trim($_POST['findings']),trim($_POST['impression']),current_user_id(),$rid]);}
  else{$q=$pdo->prepare('INSERT INTO radiology_results(order_id,modality,technique,findings,impression,reported_by,reported_at) VALUES(?,?,?,?,?,?,NOW())');$q->execute([$oid,trim($_POST['modality']),trim($_POST['technique']),trim($_POST['findings']),trim($_POST['impression']),current_user_id()]);}
  $pdo->prepare("UPDATE cpoe_orders SET status='completed',completed_at=NOW() WHERE id=?")->execute([$oid]);audit($pdo,'REPORT','RADIOLOGY',$oid,'Laporan radiologi difinalisasi.');$msg='Laporan radiologi berhasil dirilis.';
 }
}
$where="WHERE o.order_type='radiology'";$params=[];
if(is_role('patient')){$where.=' AND o.patient_id=? AND rr.reported_at IS NOT NULL';$params[] = current_patient_id($pdo)??0;}
elseif(is_role('doctor')){$where.=' AND EXISTS(SELECT 1 FROM encounters e WHERE e.id=o.encounter_id AND e.doctor_id=?)';$params[]=doctor_id($pdo);}
elseif(is_role('nurse')){$where.=' AND EXISTS(SELECT 1 FROM vital_signs v WHERE v.patient_id=o.patient_id AND v.recorded_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR))';}
$sql="SELECT o.*,p.name patient,p.mrn,rr.id result_id,rr.modality,rr.technique,rr.findings,rr.impression,rr.reported_at FROM cpoe_orders o JOIN patients p ON p.id=o.patient_id LEFT JOIN radiology_results rr ON rr.order_id=o.id $where ORDER BY o.ordered_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();include __DIR__.'/includes/header.php';?>
<?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?>
<div class="grid two"><div class="card"><div class="card-header"><div><h3 class="section-title">Radiology Worklist</h3><p class="section-subtitle"><?=count($orders)?> imaging order dalam scope.</p></div></div><div class="table-wrap"><table><tr><th>Pasien</th><th>Exam</th><th>Priority</th><th>Status</th><th>Impression</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['patient'])?><br><span class="mini"><?=h($o['mrn'])?></span></td><td><?=h($o['order_name'])?></td><td><?=h(strtoupper($o['priority']))?></td><td><?=h($o['status'])?></td><td><?=h($o['impression']?:'Pending')?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><?php if(is_role('radiology')):?><div class="card-header"><div><h3 class="section-title">Radiology Report</h3><p class="section-subtitle">Final report dibuat radiolog. Setelah released, clinical team membaca secara read-only.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Order</label><select name="order_id" required><?php foreach($orders as $o):?><option value="<?=$o['id']?>">#<?=$o['id']?> — <?=h($o['patient'].' · '.$o['order_name'])?></option><?php endforeach;?></select><br><label>Modality</label><input name="modality" required placeholder="X-ray / CT / MRI / USG"><br><label>Technique</label><textarea name="technique" required></textarea><br><label>Findings</label><textarea name="findings" required></textarea><br><label>Impression</label><textarea name="impression" required></textarea><button class="btn primary" style="margin-top:10px">✓ Finalize Report</button></form><?php else:?><div class="notice"><div>◉</div><div><strong>Read-only imaging viewer</strong><span>Dokter/perawat/Rekam Medis melihat hasil tanpa dapat mengubah laporan.</span></div></div><?php endif;?></div></div><?php include __DIR__.'/includes/footer.php';?>